contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set up by ensuring the vault has some tokens by calling buyShares from this contract,
    // then immediately sell the exact shares we received back. We assert that after the round-trip
    // this contract's share balance is unchanged (i.e., minted then burned), and totalSupply is restored
    // to previous value, and that the contract did not increase its token balances as a result.
    function run(address to, uint256 baseMin, uint256 quoteMin, bytes calldata data, uint256 deadline) public payable {
        require(deadline >= block.timestamp, "PRECONDITION_DEADLINE");
        // Read initial observable state
        uint256 beforeShares = c.balanceOf(address(this));
        (uint256 mtBaseBefore, uint256 mtQuoteBefore) = c.getMtFeeTotal();
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 vaultBaseBefore;
        uint256 vaultQuoteBefore;
        (vaultBaseBefore, vaultQuoteBefore) = c.getVaultReserve();
        uint256 contractBaseBefore = address(c)._getBalance();

        // Call buyShares sending no value (assume tokens already in vault for this test harness)
        // buyShares returns (shares, baseInput, quoteInput)
        (uint256 sharesMinted, uint256 baseInput, uint256 quoteInput) = c.buyShares(address(this));

        // Immediately sell the same shares back
        bool reverted;
        uint256 baseAmount;
        uint256 quoteAmount;
        try c.sellShares(sharesMinted, to, baseMin, quoteMin, data, deadline) returns (uint256 b, uint256 q) {
            reverted = false;
            baseAmount = b;
            quoteAmount = q;
        } catch {
            reverted = true;
        }

        // Read final observable state
        uint256 afterShares = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();
        (uint256 mtBaseAfter, uint256 mtQuoteAfter) = c.getMtFeeTotal();
        (uint256 vaultBaseAfter, uint256 vaultQuoteAfter) = c.getVaultReserve();

        // General invariant we assert:
        // If the sell did not revert, then this contract's share balance must be equal to before (round-trip did not create shares),
        // totalSupply must be equal to before, and market-level MT fees didn't decrease.
        assert(
            reverted || (
                afterShares == beforeShares
                && totalSupplyAfter == totalSupplyBefore
                && mtBaseAfter >= mtBaseBefore
                && mtQuoteAfter >= mtQuoteBefore
            )
        );
    }

    // helper: since we cannot call address(c).balance directly as a function, create a small inline assembly helper
    // But per constraints we may only observe address(c).balance; however solidity allows address(c).balance in expression.
    // Provide fallback to receive ether if needed by c interactions.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property test
    // We attempt to buy shares (no ETH sent) and then sell exactly the minted shares.
    // Parameters: to (recipient for sellShares token callback), baseMin and quoteMin minimums,
    // data passed to sellShares call, and deadline for sellShares.
    function run(address to, uint256 baseMin, uint256 quoteMin, bytes calldata data, uint256 deadline) public payable {
        require(deadline >= block.timestamp, "PRECONDITION_DEADLINE");

        // Observe initial public state
        uint256 beforeShares = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();
        (uint256 mtBaseBefore, uint256 mtQuoteBefore) = c.getMtFeeTotal();

        // Try to buy shares. This is a state-changing call and must be top-level.
        // buyShares may revert; if it does, we treat that as a non-success path and assert trivially false
        // by making the final assertion allow the buy to revert (we require that the checked property only
        // applies when buy succeeded and the subsequent sell did not revert).
        uint256 sharesMinted;
        uint256 baseInput;
        uint256 quoteInput;
        bool buyReverted = false;
        try c.buyShares(address(this)) returns (uint256 s, uint256 b, uint256 q) {
            sharesMinted = s;
            baseInput = b;
            quoteInput = q;
        } catch {
            buyReverted = true;
        }

        // If buy reverted, we cannot continue with the main property — assert allows that case by making
        // the main invariant vacuously true when buy failed. Otherwise attempt to sell the minted shares.
        bool sellReverted = false;
        uint256 baseAmountReturned = 0;
        uint256 quoteAmountReturned = 0;
        if (!buyReverted) {
            try c.sellShares(sharesMinted, to, baseMin, quoteMin, data, deadline) returns (uint256 bOut, uint256 qOut) {
                baseAmountReturned = bOut;
                quoteAmountReturned = qOut;
            } catch {
                sellReverted = true;
            }
        }

        // Read final observable state
        uint256 afterShares = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();
        (uint256 mtBaseAfter, uint256 mtQuoteAfter) = c.getMtFeeTotal();

        // General rule to assert:
        // If buyShares succeeded and the subsequent sellShares of the exact minted amount did not revert,
        // then this contract's share balance must be equal to before (round-trip didn't leave extra shares),
        // totalSupply must be restored to previous value, and maintainer fee totals must not have decreased.
        assert(
            buyReverted || sellReverted || (
                afterShares == beforeShares
                && totalSupplyAfter == totalSupplyBefore
                && mtBaseAfter >= mtBaseBefore
                && mtQuoteAfter >= mtQuoteBefore
            )
        );
    }

    receive() external payable {}
}

