contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run sells shares: ensure when sellShares does not revert, totalSupply and caller balance decrease by shareAmount.
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(deadline >= block.timestamp, "precondition: deadline must be >= now");
        // We will call sellShares from this contract, so first ensure this contract has enough shares by minting via buyShares.
        // Call buyShares by sending tokens is not possible here; instead rely on the freshly deployed c having a buyable state.
        // We attempt to buy shares by calling buyShares(to) where to is address(this) to receive shares.
        // We don't send Ether; buyShares reads token balances, so this may mint zero shares and revert; we just proceed regardless.
        // Capture pre-state
        uint256 preTotal = c.totalSupply();
        uint256 preBalance = c.balanceOf(address(this));

        // Try to call sellShares and record whether it reverted.
        bool reverted;
        uint256 retBase;
        uint256 retQuote;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 postTotal = c.totalSupply();
        uint256 postBalance = c.balanceOf(address(this));

        // If sellShares succeeded (not reverted) then exactly shareAmount must have been burned from totalSupply and from caller's balance.
        // Because sellShares requires shareAmount <= _SHARES_[msg.sender], this also implies preBalance >= shareAmount when not reverted.
        // Formulate the general rule: if not reverted then preTotal == postTotal + shareAmount and preBalance == postBalance + shareAmount.
        assert(reverted || (preTotal == postTotal + shareAmount && preBalance == postBalance + shareAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful buyShares(to) call increases both the recipient's balance
    // and totalSupply by exactly the returned shares value. The function takes no ETH.
    function run(address to) public payable {
        require(to != address(0), "to must be non-zero");

        // Observe before-values via public getters
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(to);

        bool reverted;
        uint256 retShares;
        uint256 retBaseInput;
        uint256 retQuoteInput;

        // Call buyShares and capture revert state
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            retShares = shares;
            retBaseInput = baseInput;
            retQuoteInput = quoteInput;
        } catch {
            reverted = true;
        }

        // If call reverted, we cannot observe state-change; assert that in that case
        // at least no visible change to totalSupply or recipient balance happened.
        // If it didn't revert, shares must be > 0 (buyShares requires base input > 0 and mints > 0)
        if (reverted) {
            // After revert, public observables should remain equal to before
            assert(c.totalSupply() == totalBefore && c.balanceOf(to) == balBefore);
        } else {
            // On success, returned shares equal the increase in recipient balance
            // and equal the increase in totalSupply.
            assert(retShares == c.balanceOf(to) - balBefore && retShares == c.totalSupply() - totalBefore);

            // Additionally, shares must be strictly positive when call succeeded
            assert(retShares > 0);

            // buyShares requires baseInput > 0; ensure the reported baseInput is > 0
            assert(retBaseInput > 0);
        }
    }

    receive() external payable {}
}

