            (reverted && c.totalSupply() == totalBefore && c.balanceOf(to) == balBefore)
            ||
            // If not reverted then returned shares equal increases in both balance and totalSupply
            (!reverted && retShares == c.balanceOf(to) - balBefore && retShares == c.totalSupply() - totalBefore && retShares > 0 && retBaseInput > 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0), "nonzero");

        // Observe before values via public getters
        uint256 totalBefore = c.totalSupply();
        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(from, address(this));

        // Attempt to perform transferFrom(from,to,amount) as this contract
        bool reverted;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balFromAfter = c.balanceOf(from);
        uint256 balToAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(from, address(this));

        // Assert: If call succeeded then totalSupply unchanged and balances updated consistently by amount and allowance decreased accordingly;
        // If call reverted then nothing observable changed (totalSupply and balances and allowance unchanged).
        assert(
            (!reverted &&
                totalAfter == totalBefore &&
                // when succeeded, from decreases by exactly amount and to increases by exactly amount
                balFromAfter + amount == balFromBefore &&
                balToAfter == balToBefore + amount &&
                // allowance must have been sufficient before and decreased (or stayed if unlimited) but cannot increase
                allowanceBefore >= amount && allowanceAfter <= allowanceBefore
            ) || (
                reverted &&
                totalAfter == totalBefore &&
                balFromAfter == balFromBefore &&
                balToAfter == balToBefore &&
                allowanceAfter == allowanceBefore
            )
        );
    }

    receive() external payable {}
}
